CREATE TABLE public.content_team_members (owner_id uuid NOT NULL, member_id uuid NOT NULL, joined_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, PRIMARY KEY(owner_id,member_id), CHECK(owner_id<>member_id));
GRANT SELECT ON public.content_team_members TO authenticated; GRANT ALL ON public.content_team_members TO service_role; ALTER TABLE public.content_team_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_member_read ON public.content_team_members FOR SELECT TO authenticated USING(owner_id=auth.uid() OR member_id=auth.uid());
CREATE TABLE public.content_team_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,email text NOT NULL,token_hash text NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',accepted_at timestamptz,revoked_at timestamptz);
GRANT ALL ON public.content_team_invites TO service_role; ALTER TABLE public.content_team_invites ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.content_team_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,author_id uuid NOT NULL,playlist_id uuid REFERENCES public.playlists(id) ON DELETE SET NULL,name text NOT NULL,items jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
GRANT SELECT ON public.content_team_drafts TO authenticated; GRANT ALL ON public.content_team_drafts TO service_role; ALTER TABLE public.content_team_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_draft_read ON public.content_team_drafts FOR SELECT TO authenticated USING(owner_id=auth.uid() OR (author_id=auth.uid() AND EXISTS(SELECT 1 FROM public.content_team_members m WHERE m.owner_id=content_team_drafts.owner_id AND m.member_id=auth.uid() AND revoked_at IS NULL)));
CREATE FUNCTION public.content_team_data() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;
RETURN jsonb_build_object('members',COALESCE((SELECT jsonb_agg(jsonb_build_object('member_id',m.member_id,'email',p.email,'name',p.full_name,'revoked_at',m.revoked_at)) FROM public.content_team_members m LEFT JOIN public.profiles p ON p.id=m.member_id WHERE m.owner_id=auth.uid()),'[]'::jsonb),'invites',COALESCE((SELECT jsonb_agg(to_jsonb(i)-'token_hash'-'owner_id') FROM public.content_team_invites i WHERE owner_id=auth.uid()),'[]'::jsonb),'workspaces',COALESCE((SELECT jsonb_agg(jsonb_build_object('owner_id',m.owner_id,'name',COALESCE(p.org_name,p.full_name,'Espace partagé'),'playlists',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',l.id,'name',l.name,'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('mediaId',i.media_id,'duration',i.duration) ORDER BY position) FROM public.playlist_items i WHERE i.playlist_id=l.id),'[]'::jsonb))) FROM public.playlists l WHERE l.user_id=m.owner_id),'[]'::jsonb),'media',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'type',x.type,'size',x.size,'duration',x.duration)) FROM public.media x WHERE x.user_id=m.owner_id),'[]'::jsonb))) FROM public.content_team_members m LEFT JOIN public.profiles p ON p.id=m.owner_id WHERE m.member_id=auth.uid() AND revoked_at IS NULL),'[]'::jsonb),'drafts',COALESCE((SELECT jsonb_agg(to_jsonb(d) ORDER BY created_at DESC) FROM public.content_team_drafts d WHERE d.owner_id=auth.uid() OR (d.author_id=auth.uid() AND EXISTS(SELECT 1 FROM public.content_team_members m WHERE m.owner_id=d.owner_id AND member_id=auth.uid() AND revoked_at IS NULL))),'[]'::jsonb)); END $$;
CREATE FUNCTION public.invite_content_member(p_email text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE token text; result uuid; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;
IF p_email IS NULL OR length(p_email)>254 OR p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR lower(p_email)=lower(auth.jwt()->>'email') THEN RAISE EXCEPTION 'Invalid email'; END IF;
IF (SELECT count(*) FROM public.content_team_invites WHERE owner_id=auth.uid() AND created_at IS NULL)>100 THEN NULL; END IF;
token:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
INSERT INTO public.content_team_invites(owner_id,email,token_hash) VALUES(auth.uid(),lower(trim(p_email)),md5(token)) RETURNING id INTO result; RETURN jsonb_build_object('id',result,'token',token); END $$;
CREATE FUNCTION public.accept_content_invite(p_id uuid,p_token text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.content_team_invites; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;
SELECT * INTO i FROM public.content_team_invites WHERE id=p_id AND token_hash=md5(p_token) AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at>now() FOR UPDATE;
IF NOT FOUND OR i.email IS DISTINCT FROM lower(auth.jwt()->>'email') OR i.owner_id=auth.uid() THEN RAISE EXCEPTION 'Invitation invalid'; END IF;
INSERT INTO public.content_team_members(owner_id,member_id) VALUES(i.owner_id,auth.uid()) ON CONFLICT(owner_id,member_id) DO UPDATE SET revoked_at=NULL,joined_at=now(); UPDATE public.content_team_invites SET accepted_at=now() WHERE id=i.id; END $$;
CREATE FUNCTION public.revoke_content_access(p_member uuid,p_invite uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;
IF p_member IS NOT NULL THEN UPDATE public.content_team_members SET revoked_at=now() WHERE owner_id=auth.uid() AND member_id=p_member; END IF;
IF p_invite IS NOT NULL THEN UPDATE public.content_team_invites SET revoked_at=now() WHERE owner_id=auth.uid() AND id=p_invite; END IF; END $$;
CREATE FUNCTION public.submit_content_draft(p_owner uuid,p_playlist uuid,p_name text,p_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; v jsonb; BEGIN
IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.content_team_members WHERE owner_id=p_owner AND member_id=auth.uid() AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF p_name IS NULL OR length(trim(p_name)) NOT BETWEEN 1 AND 80 OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items)>100 THEN RAISE EXCEPTION 'Invalid draft'; END IF;
IF p_playlist IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.playlists WHERE id=p_playlist AND user_id=p_owner) THEN RAISE EXCEPTION 'Forbidden'; END IF;
FOR v IN SELECT value FROM jsonb_array_elements(p_items) LOOP IF (v->>'duration')::integer IS NULL OR (v->>'duration')::integer NOT BETWEEN 1 AND 86400 OR NOT EXISTS(SELECT 1 FROM public.media WHERE id=(v->>'mediaId')::uuid AND user_id IN (p_owner,auth.uid())) THEN RAISE EXCEPTION 'Invalid media'; END IF; END LOOP;
INSERT INTO public.content_team_drafts(owner_id,author_id,playlist_id,name,items) VALUES(p_owner,auth.uid(),p_playlist,trim(p_name),p_items) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.review_content_draft(p_id uuid,p_approve boolean,p_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.content_team_drafts; target uuid; BEGIN
SELECT * INTO d FROM public.content_team_drafts WHERE id=p_id AND owner_id=auth.uid() AND status='pending' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.content_team_members WHERE owner_id=d.owner_id AND member_id=d.author_id AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Member revoked'; END IF;
IF p_approve THEN
IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items)>100 THEN RAISE EXCEPTION 'Invalid draft'; END IF;
target:=d.playlist_id; IF target IS NULL THEN INSERT INTO public.playlists(user_id,name) VALUES(auth.uid(),d.name) RETURNING id INTO target; ELSE UPDATE public.playlists SET name=d.name WHERE id=target AND user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Forbidden'; END IF; END IF;
PERFORM public.replace_playlist_items(target,p_items);
END IF;
UPDATE public.content_team_drafts SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,reviewed_at=now() WHERE id=d.id; RETURN target; END $$;
REVOKE ALL ON FUNCTION public.content_team_data(),public.invite_content_member(text),public.accept_content_invite(uuid,text),public.revoke_content_access(uuid,uuid),public.submit_content_draft(uuid,uuid,text,jsonb),public.review_content_draft(uuid,boolean,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.content_team_data(),public.invite_content_member(text),public.accept_content_invite(uuid,text),public.revoke_content_access(uuid,uuid),public.submit_content_draft(uuid,uuid,text,jsonb),public.review_content_draft(uuid,boolean,jsonb) TO authenticated;